import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("RELIANCE.NS");
  const [loading, setLoading] = useState(false);

  const stockList = [
    { name: "Reliance Industries", symbol: "RELIANCE.NS" },
    { name: "Tata Motors (Potential BUY)", symbol: "TATAMOTORS.NS" },
    { name: "Adani Enterprises (Potential AVOID)", symbol: "ADANIENT.NS" },
    { name: "TCS", symbol: "TCS.NS" },
    { name: "HDFC Bank", symbol: "HDFCBANK.NS" },
    { name: "Infosys", symbol: "INFY.NS" },
    { name: "Zomato", symbol: "ZOMATO.NS" },
    { name: "Paytm", symbol: "PAYTM.NS" }
  ];

  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        setData(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Backend Error:", err);
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData(selectedStock);
  }, [selectedStock]);

  return (
    <div style={{ backgroundColor: '#0e1117', color: '#c9d1d9', minHeight: '100vh', padding: '20px', fontFamily: 'monospace' }}>
      
      <div style={{ borderBottom: '1px solid #30363d', paddingBottom: '10px', marginBottom: '20px' }}>
        <h2 style={{ color: '#58a6ff' }}>🛡️ QuantShield AI: Advanced Portfolio Optimizer</h2>
      </div>

      {/* Stock Selection Dropdown */}
      <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d', marginBottom: '20px' }}>
        <label style={{ marginRight: '15px', fontWeight: 'bold' }}>📁 SELECT ASSET:</label>
        <select 
          value={selectedStock} 
          onChange={(e) => setSelectedStock(e.target.value)}
          style={{ background: '#0d1117', color: 'white', border: '1px solid #58a6ff', padding: '10px', borderRadius: '5px', width: '350px', fontSize: '16px' }}
        >
          {stockList.map(s => <option key={s.symbol} value={s.symbol}>{s.name} ({s.symbol})</option>)}
        </select>
        {loading && <span style={{marginLeft: '15px', color: '#f1e05a'}}>⚡ Running AI Regression...</span>}
      </div>

      {data && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.5fr', gap: '20px' }}>
          
          {/* Left Side: Market Analysis */}
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
            <h3 style={{ color: '#ff4b4b' }}>📊 Risk Analysis</h3>
            <div style={{ lineHeight: '3', fontSize: '18px' }}>
              <div style={{ borderBottom: '1px solid #21262d' }}>Current Price: <b style={{float: 'right', color: '#58a6ff'}}>₹{data.current_price}</b></div>
              <div style={{ borderBottom: '1px solid #21262d' }}>Volatility Index: <b style={{float: 'right', color: '#f85149'}}>{data.volatility}</b></div>
              <div style={{ borderBottom: '1px solid #21262d' }}>Regime Detection: <b style={{float: 'right'}}>{data.regime}</b></div>
              <div style={{ borderBottom: '1px solid #21262d' }}>BSI (Momentum): <b style={{float: 'right', color: '#d2a8ff'}}>{data.bsi_score}</b></div>
            </div>

            {/* Ghost Hedge System Status */}
            <div style={{ 
              marginTop: '40px', padding: '20px', textAlign: 'center', borderRadius: '8px',
              background: data.regime === "STRESS" ? '#4a151b' : '#064e3b',
              border: `2px solid ${data.regime === "STRESS" ? '#f85149' : '#238636'}`,
              color: 'white', fontWeight: 'bold', fontSize: '1.2rem'
            }}>
              🛡️ GHOST HEDGE: {data.regime === "STRESS" ? "SYSTEM ACTIVE" : "MONITORING"}
            </div>
          </div>

          {/* Right Side: Prediction & Forecast */}
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
            
            {/* New: 2-Day AI Prediction Box */}
            <div style={{ background: '#0d1117', padding: '15px', borderRadius: '10px', border: '1px solid #30363d', marginBottom: '20px' }}>
              <h4 style={{ color: '#f1e05a', marginTop: 0 }}>🔮 AI PRICE PREDICTION (NEXT 2 DAYS)</h4>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div style={{ fontSize: '16px' }}>
                  <p style={{ margin: '5px 0' }}>Day 1: <b>₹{data.prediction?.day1}</b></p>
                  <p style={{ margin: '5px 0' }}>Day 2: <b>₹{data.prediction?.day2}</b></p>
                </div>
                <div style={{ 
                  textAlign: 'center', padding: '10px 20px', borderRadius: '5px',
                  background: data.prediction?.trend === "UP" ? '#238636' : '#f85149'
                }}>
                  <span style={{ fontSize: '10px', display: 'block' }}>2-DAY TREND</span>
                  <h3 style={{ margin: 0 }}>{data.prediction?.trend} ({data.prediction?.pct})</h3>
                </div>
              </div>
            </div>

            <h3 style={{ color: '#58a6ff' }}>🎲 Portfolio Simulation (₹10,000)</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px' }}>
              <div style={{ background: '#0d1117', padding: '15px', borderRadius: '10px', borderLeft: '5px solid #238636' }}>
                <p style={{ margin: 0, color: '#8b949e', fontSize: '12px' }}>Expected Value</p>
                <h2 style={{ color: '#3fb950', margin: '5px 0' }}>₹{data.forecast?.expected}</h2>
              </div>
              <div style={{ background: '#0d1117', padding: '15px', borderRadius: '10px', borderLeft: '5px solid #f85149' }}>
                <p style={{ margin: 0, color: '#8b949e', fontSize: '12px' }}>Worst Case Risk</p>
                <h2 style={{ color: '#f85149', margin: '5px 0' }}>₹{data.forecast?.worst_case}</h2>
              </div>
            </div>

            {/* AI VERDICT */}
            <div style={{ 
              marginTop: '25px', padding: '20px', textAlign: 'center', borderRadius: '10px', 
              background: data.decision === "BUY" ? '#238636' : data.decision === "AVOID" ? '#f85149' : '#f1e05a',
              color: data.decision === "HOLD" ? 'black' : 'white',
              fontSize: '28px', fontWeight: 'extrabold'
            }}>
              🤖 AI VERDICT: {data.decision}
            </div>
          </div>

        </div>
      )}
    </div>
  );
}

export default App;
